/**
 * Header marking a route file as generated by the SMRT vite plugin.
 *
 * Shared by every route emitter (`sveltekit-generator.ts`,
 * `changes-route.ts`, `sync-apply-route.ts`): the cleanup pass deletes exactly
 * the `+server.ts` files that start with this header, so all emitters MUST use
 * the same constant — a divergent copy would orphan generated files. The same
 * header decides ownership before any write (`generated-route-ownership.ts`):
 * a route file without it is application code and is never replaced.
 */
export const AUTO_GENERATED_ROUTE_HEADER =
  '// Auto-generated by @smrt/core vite plugin';
